import random
from IPython.display import Image

def guess_number():
    secret_num = random.randint(1, 10)
    guess = int(input("Guess a number between 1 and 10: "))

    Image(filename='celebrate.png')

    if guess <= 0:
        print("You must guess a positive number.")
    elif guess >= 11:
        print("Your guess must be 10 or less.")
    elif guess < secret_num:
        print("You're too low!")
    elif guess > secret_num:
        print("You're too high!")
    else:
        print("You got it!")
        guess_number()

guess_number()

